#ifndef FOCUS_STUB_NM_PRIOQ_H
#define FOCUS_STUB_NM_PRIOQ_H

/* Minimal stand-in for src/libnm-glib-aux/nm-prioq.h, used only so that the
 * real src/libnm-lldp/nm-lldp-rx-internal.h can be compiled in isolation. */
typedef struct {
    int _stub;
} NMPrioq;

#endif /* FOCUS_STUB_NM_PRIOQ_H */

#ifndef FOCUS_STUB_NM_LLDP_RX_H
#define FOCUS_STUB_NM_LLDP_RX_H

/* Minimal stand-in for src/libnm-lldp/nm-lldp-rx.h so that the real
 * nm-lldp-rx-internal.h can be compiled in isolation. */

#include <stddef.h>

typedef struct _NMLldpRX NMLldpRX;

typedef struct {
    char *log_ifname;
    char *log_uuid;
} NMLldpRXConfig;

/* Opaque GLib types referenced by struct _NMLldpRX. */
typedef struct _GMainContext GMainContext;
typedef struct _GSource      GSource;
typedef struct _GHashTable   GHashTable;

#define G_STMT_START do
#define G_STMT_END   while (0)

#endif /* FOCUS_STUB_NM_LLDP_RX_H */

/* Focused regression for the _NMLOG2 macro single-evaluation invariant.
 *
 * The header under test (src/libnm-lldp/nm-lldp-rx-internal.h) is copied
 * verbatim into the harness include directory by run.sh, so this test exercises
 * the exact bytes of the target header.
 *
 * Invariant: the `level` argument of _NMLOG2 must be evaluated exactly once,
 * and the level passed to _nm_log must equal the level used by the
 * _NMLOG2_ENABLED gate.
 *
 * Vulnerable baseline: `_nm_log(level, ...)` re-evaluates the argument, so a
 * side-effecting level is evaluated twice and the logged level can differ from
 * the gate level.
 * Fixed candidate: `_nm_log(_level, ...)` uses the single captured value.
 */

#include <stdio.h>
#include <string.h>

#include "nm-lldp-rx-internal.h"

static int s_eval_count = 0;

static NMLogLevel
side_effect_level(void)
{
    s_eval_count++;
    return (NMLogLevel) (100 + s_eval_count);
}

static NMLogLevel s_gate_level   = -1;
static NMLogLevel s_logged_level = -1;

/* Stubs matching the real logging protocol. */
int
nm_logging_enabled(NMLogLevel level, int domain)
{
    (void) domain;
    s_gate_level = level;
    return 1;
}

void
test_capture_log_level(NMLogLevel level)
{
    s_logged_level = level;
}

int
main(void)
{
    NMLldpRX rx;

    memset(&rx, 0, sizeof(rx));
    rx.config.log_ifname = (char *) "eth0";
    rx.config.log_uuid   = NULL;

    s_eval_count   = 0;
    s_gate_level   = -1;
    s_logged_level = -1;

    _NMLOG2(side_effect_level(), &rx, "probe");

    printf("eval_count=%d gate_level=%d logged_level=%d\n",
           s_eval_count,
           (int) s_gate_level,
           (int) s_logged_level);

    if (s_eval_count != 1) {
        fprintf(stderr,
                "FAIL: level argument evaluated %d time(s), expected exactly 1\n",
                s_eval_count);
        return 1;
    }
    if (s_gate_level != s_logged_level) {
        fprintf(stderr,
                "FAIL: gate level %d != logged level %d\n",
                (int) s_gate_level,
                (int) s_logged_level);
        return 1;
    }

    printf("PASS: level evaluated once; gate level == logged level\n");
    return 0;
}

